let records=[],current=null,map=null,markers=[],dataset=null;
const el=id=>document.getElementById(id);
const normalize=s=>s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[’']/g,'');
function para(text,parent){const p=document.createElement('p');p.textContent=text;parent.append(p);return p}
function linkify(text,node){const pattern=/https?:\/\/[^\s)]+/g;let at=0;for(const match of text.matchAll(pattern)){node.append(document.createTextNode(text.slice(at,match.index)));let url=match[0].replace(/[.,;]+$/,'');const a=document.createElement('a');a.href=url;a.textContent=url;a.target='_blank';a.rel='noopener';node.append(a);at=match.index+url.length}node.append(document.createTextNode(text.slice(at)))}
function icon(r,selected=false){return L.divIcon({html:'<div class="dot '+(r.statusKey==='pending'?'pending ':'')+(selected?'selected':'')+'"></div>',className:'',iconSize:[28,28],iconAnchor:[14,14]})}
function openPlace(r){document.getElementById('atlas').classList.add('exploring');document.getElementById('placespanel').hidden=true;document.getElementById('placestoggle').setAttribute('aria-expanded','false');renderPlacePhoto(r);current=r;window.stopCard?.();el('card').hidden=false;el('card').scrollTop=0;el('name').textContent=r.name;el('status').textContent=r.status;el('summary').textContent=r.summary;el('history').style.display='none';el('history').replaceChildren();el('placeSources').replaceChildren();el('editorialnote').hidden=r.id!==1;el('editorialnote').textContent=r.id===1?t('editorialWarning'):'';
 const details=document.createElement('details'),summary=document.createElement('summary');summary.textContent=t('sourcesForPlace');details.append(summary);const text=r.paragraphs.join(' ');const cited=dataset.references.filter(s=>s.length>100&&s.includes('(')&&text.includes(s.split(',')[0]));for(const ref of cited){const p=document.createElement('p');linkify(ref,p);details.append(p)}if(!cited.length)para(t('sourceNote'),details);el('placeSources').append(details);
 records.forEach(x=>{if(markers[x.id])markers[x.id].setIcon(icon(x,x.id===r.id))});document.querySelectorAll('.place').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.id)===r.id)));window.animateCard?.(r);window.updateChatScope?.();
}
function visibleRecords(){const query=normalize(el('search').value),filter=el('filter').value;return records.filter(r=>(!query||normalize(r.name+' '+r.title+' '+r.paragraphs.join(' ')).includes(query))&&(!filter||r.kindKey===filter||r.statusKey===filter))}
function list(){el('list').replaceChildren();const matches=visibleRecords();el('resultcount').textContent=matches.length+' / '+records.length+' '+t('count');if(!matches.length)para(t('noResults'),el('list'));
 records.forEach(r=>{const match=matches.includes(r);if(map&&markers[r.id]){if(match&&!map.hasLayer(markers[r.id]))markers[r.id].addTo(map);else if(!match&&map.hasLayer(markers[r.id]))map.removeLayer(markers[r.id])}if(match){const b=document.createElement('button');b.className='place';b.dataset.id=r.id;b.setAttribute('aria-pressed',String(current?.id===r.id));const thumb=document.createElement('img');thumb.src=PHOTOS[r.id].src;thumb.alt='';thumb.loading='lazy';thumb.width=54;thumb.height=54;b.append(thumb);const label=document.createElement('span');label.className='place-name';label.textContent=r.name;b.append(label);const s=document.createElement('small');s.textContent=r.status;b.append(s);b.onclick=()=>{openPlace(r);if(map)map.setView([r.lat,r.lon],16)};el('list').append(b)}});
}
function framework(){el('framework').replaceChildren();dataset.framework.forEach((text,i)=>{const section=document.createElement('section');const h=document.createElement('h3');h.textContent=t('frameworkHeadings')[i];section.append(h);para(text,section);el('framework').append(section)});el('referenceList').replaceChildren();let group;
 dataset.references.forEach(text=>{if(text.length<100&&!text.includes('(')){group=document.createElement('details');const summary=document.createElement('summary');summary.textContent=text;group.append(summary);const ol=document.createElement('ol');group.append(ol);el('referenceList').append(group)}else{if(!group)return;const li=document.createElement('li');linkify(text,li);group.querySelector('ol').append(li)}})
}
function translateUI(){document.querySelectorAll('.leaflet-control-zoom-in,.leaflet-control-zoom-out').forEach(n=>{const label=n.classList.contains('leaflet-control-zoom-in')?(lang==='ca'?'Apropa':'Acercar'):(lang==='ca'?'Allunya':'Alejar');n.title=label;n.setAttribute('aria-label',label)});document.documentElement.lang=lang;document.title=(lang==='ca'?'Memòria Colonial':'Memoria Colonial')+' · Barcelona';document.querySelector('meta[name=description]').content=t('projectLead');document.querySelectorAll('[data-i18n]').forEach(n=>n.innerHTML=t(n.dataset.i18n));document.querySelectorAll('[data-i18n-placeholder]').forEach(n=>n.placeholder=t(n.dataset.i18nPlaceholder));document.querySelectorAll('[data-i18n-aria]').forEach(n=>n.setAttribute('aria-label',t(n.dataset.i18nAria)));document.querySelectorAll('[data-lang]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.lang===lang)));document.querySelector('.brand').setAttribute('aria-label',(lang==='ca'?'Memòria Colonial — Inici':'Memoria Colonial — Inicio'));document.querySelector('.languages').setAttribute('aria-label',lang==='ca'?'Idioma':'Idioma');}
let languageRequest=0;
async function setLanguage(next){const request=++languageRequest;const previousLang=lang;lang=next;translateUI();try{const response=await fetch('data-'+next+'.json');if(!response.ok)throw Error('content');const data=await response.json();if(request!==languageRequest)return;const id=current?.id,wasOpen=!el('card').hidden,hadHistory=el('history').style.display==='block';dataset=data;records=data.records;try{localStorage.setItem('atlas-language',next)}catch{}const url=new URL(location.href);url.searchParams.set('lang',next);window.history.replaceState(null,'',url);framework();renderPhotoCredits();
 markers.forEach(m=>m&&map?.removeLayer(m));markers=[];if(map)records.forEach(r=>{markers[r.id]=L.marker([r.lat,r.lon],{icon:icon(r),title:r.name,alt:r.name,keyboard:true}).addTo(map).bindTooltip(r.name).on('click',()=>openPlace(r))});if(wasOpen&&id!==undefined){openPlace(records.find(r=>r.id===id));if(hadHistory)window.showHistory?.()}else current=null;list();window.dispatchEvent(new CustomEvent('atlaslanguage',{detail:{lang}}));map?.invalidateSize();
 }catch(e){if(request!==languageRequest)return;lang=previousLang;translateUI();el('resultcount').textContent=t('dataError')}
}
if(window.L){map=L.map('map',{scrollWheelZoom:false,zoomControl:false}).setView([41.386,2.177],14);L.control.zoom({position:'bottomright'}).addTo(map);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'}).addTo(map)}else el('maperror').hidden=false;
el('search').oninput=list;el('filter').onchange=list;el('close').onclick=()=>{el('card').hidden=true;window.stopCard?.();window.updateChatScope?.()};el('ask').onclick=()=>window.openAtlasChat?.();document.querySelectorAll('[data-lang]').forEach(b=>b.onclick=()=>{if(b.dataset.lang!==lang)setLanguage(b.dataset.lang)});
document.querySelectorAll('[data-route]').forEach(a=>a.addEventListener('click',()=>{el('filter').value=a.dataset.route;el('search').value='';list();map?.fitBounds(records.filter(r=>r.kindKey===a.dataset.route).map(r=>[r.lat,r.lon]),{padding:[45,45]})}));document.querySelectorAll('[data-place]').forEach(a=>a.addEventListener('click',()=>{const r=records.find(r=>r.id===Number(a.dataset.place));if(r){el('filter').value='';el('search').value='';list();openPlace(r);map?.setView([r.lat,r.lon],16)}}));
translateUI();setLanguage(lang);

function allMap(){document.getElementById('atlas').classList.add('exploring');el('card').hidden=true;window.stopCard?.();if(map&&records.length)map.fitBounds(records.map(r=>[r.lat,r.lon]),{padding:[55,55],maxZoom:14});}
el('startatlas').onclick=allMap;el('mapreset').onclick=()=>{el('search').value='';el('filter').value='';list();allMap()};
el('placestoggle').onclick=()=>{allMap();el('placespanel').hidden=!el('placespanel').hidden;el('placestoggle').setAttribute('aria-expanded',String(!el('placespanel').hidden));if(!el('placespanel').hidden)el('search').focus({preventScroll:true})};el('placesclose').onclick=()=>{el('placespanel').hidden=true;el('placestoggle').setAttribute('aria-expanded','false');el('placestoggle').focus({preventScroll:true})};document.querySelector('[data-feature]').onclick=()=>{const r=records.find(r=>r.id===1);if(r)openPlace(r)};map?.on('dragstart zoomstart',()=>document.getElementById('atlas').classList.add('exploring'));

document.addEventListener("keydown",e=>{if(e.key!=="Escape"||el("infodialog").open)return;if(!el("chatpanel").hidden){el("chatpanel").hidden=true;el("chatinput").blur()}else if(!el("placespanel").hidden){el("placesclose").click()}else if(!el("card").hidden){el("close").click()}});

const infoDialog=el('infodialog'),infoPanels=[...infoDialog.querySelectorAll('.page-section')];let infoOpener=null;
function showInfo(id){const target=id==='referencias'?'fuentes':id;const panel=infoPanels.find(p=>p.id===target);if(!panel)return false;infoPanels.forEach(p=>p.hidden=p!==panel);infoDialog.querySelectorAll('[data-panel]').forEach(a=>{a.classList.toggle('active',a.dataset.panel===target);if(a.dataset.panel===target)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});if(!infoDialog.open){infoOpener=document.activeElement;infoDialog.showModal()}infoDialog.querySelector('.info-content').scrollTop=0;return true;}
function closeInfo(){if(infoDialog.open)infoDialog.close();}
el('infoclose').onclick=()=>{closeInfo();const u=new URL(location.href);u.hash='atlas';window.history.pushState(null,'',u)};
infoDialog.addEventListener('close',()=>{if(infoOpener?.isConnected)infoOpener.focus({preventScroll:true})});
infoDialog.addEventListener('click',e=>{if(e.target===infoDialog)el('infoclose').click()});
document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#"]');if(!a)return;const id=a.getAttribute('href').slice(1);if(showInfo(id)){e.preventDefault();const u=new URL(location.href);u.hash=id;window.history.pushState(null,'',u)}else if(['atlas','inicio','contenido'].includes(id)){e.preventDefault();closeInfo();const u=new URL(location.href);u.hash='atlas';window.history.pushState(null,'',u);document.querySelector('.site-header nav a[href="#atlas"]').classList.add('active')}});
function syncInfo(){const id=location.hash.slice(1);if(!showInfo(id))closeInfo()};window.addEventListener('popstate',syncInfo);window.addEventListener('hashchange',syncInfo);syncInfo();
const headerSize=new ResizeObserver(entries=>{document.documentElement.style.setProperty('--header-height',entries[0].target.getBoundingClientRect().height+'px');map?.invalidateSize()});headerSize.observe(document.querySelector('.site-header'));
infoDialog.addEventListener('cancel',()=>{const u=new URL(location.href);u.hash='atlas';window.history.replaceState(null,'',u)});

function photoLinks(photo,parent){const credit=document.createElement('a');credit.href=photo.page;credit.target='_blank';credit.rel='noopener';const year=photo.date.match(/(?:19|20)\d{2}/)?.[0];credit.textContent=photo.author+(year?' · '+year:'');parent.append(credit,document.createTextNode(' · '));const license=document.createElement('a');license.href=photo.licenseUrl;license.target='_blank';license.rel='noopener';license.textContent=photo.license;parent.append(license);}
function renderPlacePhoto(r){const p=PHOTOS[r.id],figure=el('placephoto');figure.hidden=!p;if(!p)return;const img=figure.querySelector('img');img.src=p.src;img.alt=t('photoOf')+' '+r.name;const caption=figure.querySelector('figcaption');caption.replaceChildren();photoLinks(p,caption);}
function renderPhotoCredits(){const box=el('photocredits');box.replaceChildren();const heading=document.createElement('h3');heading.textContent=t('photoCredits');const note=document.createElement('p');note.className='note';note.textContent=t('photoTreatment');box.append(heading,note);const list=document.createElement('ul');records.forEach(r=>{const li=document.createElement('li'),name=document.createElement('strong');name.textContent=r.name;li.append(name,document.createTextNode(' · '));photoLinks(PHOTOS[r.id],li);list.append(li)});box.append(list);}
